def md(content, **kwargs):
    """Render dashboard HTML without Markdown turning it into code blocks."""
    cleaned = textwrap.dedent(content).strip()
    if "<" in cleaned and ">" in cleaned:
        return st.html(cleaned)
    return st.markdown(cleaned, **kwargs)

