def load_csv(path):
    try:
        return pd.read_csv(path)
    except Exception:
        return pd.DataFrame()


def read_tiff_preview(path):
    """Read a TIFF for dashboard display without making Rasterio mandatory."""
    import numpy as np

    # First choice: Rasterio for GeoTIFF / multi-band SAR.
    try:
        import rasterio
        with rasterio.open(path) as src:
            arr = src.read()
        if arr.ndim == 3:
            # Prefer VV-like first band for a compact visual preview.
            arr = arr[0]
        arr = arr.astype("float32")
    except Exception as rasterio_error:
        # Fallback: Pillow can read many TIFFs even when Rasterio is absent.
        try:
            from PIL import Image
            with Image.open(path) as im:
                arr = np.asarray(im).astype("float32")
            if arr.ndim == 3:
                arr = arr[0]
        except Exception as pillow_error:
            raise RuntimeError(
                f"Could not display TIFF. Rasterio: {rasterio_error}. "
                f"Pillow fallback: {pillow_error}"
            )

    finite = np.isfinite(arr)
    if not finite.any():
        return np.zeros((128, 128), dtype="uint8")

    lo, hi = np.percentile(arr[finite], [2, 98])
    if hi <= lo:
        return np.zeros(arr.shape, dtype="uint8")

    arr = np.clip((arr - lo) / (hi - lo), 0, 1)
    return (arr * 255).astype("uint8")


def pretty_column_name(name):
    name = str(name).replace("_", " ").strip()
    replacements = {
        "Mmsi": "MMSI",
        "Ais": "AIS",
        "Utc": "UTC",
        "Km": "km",
        "Id": "ID",
    }
    words = name.split()
    return " ".join(replacements.get(w, w.title()) for w in words)


def find_existing_column(df, candidates):
    lower = {str(c).lower(): c for c in df.columns}
    for candidate in candidates:
        if candidate.lower() in lower:
            return lower[candidate.lower()]
    return None


def build_vessel_display_table(rank):
    """Convert the wide evidence CSV into a judge-friendly vessel table."""
    if rank.empty:
        return pd.DataFrame()

    mmsi = find_existing_column(rank, ["mmsi", "MMSI", "mmsi_numeric"])
    name = find_existing_column(rank, ["vessel_name", "VesselName", "shipname", "name"])
    vessel_type = find_existing_column(rank, ["vessel_type", "VesselType", "ship_type", "type"])
    score = find_existing_column(rank, [
        "evidence_score", "final_score", "ranking_score", "score",
        "composite_score", "evidence_rank_score"
    ])
    distance = find_existing_column(rank, [
        "distance_km", "min_distance_km", "nearest_distance_km",
        "origin_distance_km", "spill_distance_km"
    ])
    proximity = find_existing_column(rank, [
        "proximity_score", "distance_score", "spatial_score"
    ])
    trajectory = find_existing_column(rank, [
        "trajectory_score", "track_score", "geometry_score"
    ])
    temporal = find_existing_column(rank, [
        "temporal_score", "time_compatibility_score", "temporal_compatibility"
    ])

    out = pd.DataFrame(index=rank.index)
    out["Rank"] = range(1, len(rank) + 1)
    out["MMSI"] = rank[mmsi].astype(str) if mmsi else "â€”"
    out["Vessel"] = rank[name].fillna("Unknown vessel").astype(str) if name else "Unknown vessel"
    out["Type"] = rank[vessel_type].fillna("Unknown").astype(str) if vessel_type else "Unknown"

    if score:
        out["Evidence Score"] = pd.to_numeric(rank[score], errors="coerce").round(3)
    else:
        out["Evidence Score"] = pd.NA

    if distance:
        out["Distance (km)"] = pd.to_numeric(rank[distance], errors="coerce").round(1)
    else:
        out["Distance (km)"] = pd.NA

    if proximity:
        out["Proximity"] = pd.to_numeric(rank[proximity], errors="coerce").round(2)
    if trajectory:
        out["Trajectory"] = pd.to_numeric(rank[trajectory], errors="coerce").round(2)
    if temporal:
        out["Temporal"] = pd.to_numeric(rank[temporal], errors="coerce").round(2)

    # Keep the original ranking order. Do not invent a score if the source
    # ranking already provides one.
    return out.reset_index(drop=True)

def make_map(lat=SPILL_LAT, lon=SPILL_LON):
    import folium
    from streamlit_folium import st_folium

    m = folium.Map(
        location=[lat, lon],
        zoom_start=7,
        tiles="OpenStreetMap",
        control_scale=True,
    )

    folium.Circle(
        [lat, lon],
        radius=9000,
        color="#b66b48",
        fill=True,
        fill_color="#b66b48",
        fill_opacity=.16,
        weight=2,
        tooltip="Detected spill area â€” prototype geometry",
    ).add_to(m)

    folium.CircleMarker(
        [lat, lon],
        radius=7,
        color="#c94f37",
        fill=True,
        fill_color="#c94f37",
        fill_opacity=1,
        tooltip="Spill centroid",
    ).add_to(m)

    folium.Marker(
        [ORIGIN_LAT, ORIGIN_LON],
        tooltip="Backward-drift origin estimate",
        icon=folium.Icon(color="darkblue", icon="info-sign"),
    ).add_to(m)

    st_folium(m, height=300, use_container_width=True, returned_objects=[])
    st.caption("Map base: OpenStreetMap Â· Spill and origin markers are prototype investigation outputs.")

